#!/usr/bin/env python3
"""Enrich Merged_training_data with scenario variants generated by opencode free models.

Safety model: seed payloads are already verified. Agents may ONLY reuse a seed
payload verbatim - they vary the scenario (endpoint, param, evidence, reasoning).
enrich_verify.py enforces the payload whitelist mechanically.
"""
import concurrent.futures as cf
import json
import os
import re
import subprocess

HERE = os.path.dirname(os.path.abspath(__file__))
MERGED = os.path.dirname(HERE)  # training_resources/Merged_training_data
OC = os.path.join(os.environ["LOCALAPPDATA"], "Programs", "@opencodedesktop", "resources", "opencode-cli.exe")
MODELS = [
    "opencode/glm-5.3-flash-free",
    "opencode/deepseek-v4.1-flash-free",
    "opencode/mimo-v2.6-flash-free",
    "opencode/space-bunny-free",
]
BATCHES_PER_CLASS = 8
VARIANTS_PER_BATCH = 5
MODEL_TIMEOUT = 330

CLASS_FILE = {
    "sqli": "sqli_merged_training_data.jsonl",
    "ssrf": "ssrf_merged_training_data.jsonl",
    "idor": "idor_merged_training_data.jsonl",
    "open_redirect": "open_redirect_merged_training_data.jsonl",
    "xss_reflected": "xss_reflected_merged_training_data.jsonl",
}

INJ_POINTS = "query, body, header, cookie, path"

def load_rows(cls):
    path = os.path.join(MERGED, CLASS_FILE[cls])
    return [json.loads(l) for l in open(path, encoding="utf-8") if l.strip()]

def seed_batches(cls):
    rows = load_rows(cls)
    # unique payloads, spread across the file
    seen, uniq = set(), []
    for r in rows:
        a = json.loads(r["messages"][2]["content"])
        if a["payload"] not in seen:
            seen.add(a["payload"])
            uniq.append(a)
    stride = max(1, len(uniq) // (BATCHES_PER_CLASS * 3))
    picked, i = [], 0
    while len(picked) < BATCHES_PER_CLASS * 3 and i < len(uniq):
        picked.append(uniq[i])
        i += stride
    batches = [picked[k*3:(k+1)*3] for k in range(BATCHES_PER_CLASS)]
    return [b for b in batches if len(b) == 3]

def seed_json(a):
    return {
        "payload": a["payload"], "injection_point": a["injection_point"],
        "expected_success_signal": a["expected_success_signal"],
        "reasoning": a["reasoning"],
        "example_user_message": None,  # filled by caller with the original user content
    }

def prompt_for(cls, seeds_with_user):
    seeds = []
    for a, user in seeds_with_user:
        s = seed_json(a)
        s["example_user_message"] = user
        seeds.append(s)
    return (
        f"You are generating training-data variants for a security-research SLM focused on {cls}. "
        "Below are SEED examples. Each seed payload is VERIFIED and technically correct for the "
        "technique described.\n\n"
        "Produce " + str(VARIANTS_PER_BATCH) + " NEW variant objects, output ONLY a JSON array of objects. "
        "Each object has exactly these keys: "
        '{"endpoint": string, "target_param": string, "recon_evidence": string, "planner_rationale": string, '
        '"vuln_class": string, "payload": string, "injection_point": string, '
        '"expected_success_signal": string, "confidence": number, "reasoning": string}\n'
        "STRICT RULES:\n"
        f"- payload MUST be copied VERBATIM (character for character) from one of the seeds. "
        "Choose the seed whose technique matches your variant. NEVER invent, shorten, re-encode or modify payloads.\n"
        f'- vuln_class is exactly "{cls}".\n'
        "- VARY: endpoint (a realistic 'METHOD /path' route), target_param name, "
        "recon_evidence (concrete observed behaviour that motivates exactly this payload), "
        "planner_rationale (short planner-style justification), "
        "expected_success_signal (accurate for the new context), and reasoning (1-3 sentences, "
        "technically precise, explaining why this payload fits the observed evidence).\n"
        f"- injection_point is one of: {INJ_POINTS} and must be consistent with the endpoint you imagined.\n"
        "- confidence is a float between 0.55 and 0.95, calibrated: higher when the evidence directly "
        "supports the payload mechanism, lower when the variant relies on a speculative filter behaviour.\n"
        "- Do not read or write any files. No markdown fences, no commentary - only the JSON array.\n\n"
        "SEEDS:\n" + json.dumps(seeds, ensure_ascii=False, indent=1)
    )

def parse_array(raw):
    raw = re.sub(r"```(?:json)?", "", raw)
    m = re.search(r"\[.*\]", raw, re.S)
    if not m:
        return None
    try:
        return json.loads(m.group(0))
    except json.JSONDecodeError:
        return None

def run_one(job):
    cls, bi, seeds_with_user, model = job
    outdir = os.path.join(HERE, "raw")
    os.makedirs(outdir, exist_ok=True)
    outfile = os.path.join(outdir, f"{cls}_{bi}.json")
    if os.path.exists(outfile):
        return f"{cls}_{bi}", "cached"
    try:
        proc = subprocess.run(
            [OC, "run", "-m", model, prompt_for(cls, seeds_with_user)],
            cwd=MERGED, capture_output=True, text=True, timeout=MODEL_TIMEOUT,
        )
        raw = (proc.stdout or "") + (proc.stderr or "")
        arr = parse_array(raw)
        if not isinstance(arr, list):
            return f"{cls}_{bi}", f"no-array (exit {proc.returncode})"
        rec = {"key": f"{cls}_{bi}", "model": model, "class": cls, "variants": arr, "raw_tail": raw[-400:]}
        json.dump(rec, open(outfile, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
        return f"{cls}_{bi}", f"ok ({len(arr)} variants)"
    except subprocess.TimeoutExpired:
        return f"{cls}_{bi}", "timeout"
    except Exception as e:  # noqa: BLE001
        return f"{cls}_{bi}", f"error: {type(e).__name__}"

def user_by_payload(cls):
    rows = load_rows(cls)
    m = {}
    for r in rows:
        a = json.loads(r["messages"][2]["content"])
        m.setdefault(a["payload"], r["messages"][1]["content"])
    return m

def main():
    jobs = []
    mi = 0
    for cls in CLASS_FILE:
        ubp = user_by_payload(cls)
        batches = seed_batches(cls)
        for bi, b in enumerate(batches):
            seeds_with_user = [(a, ubp[a["payload"]]) for a in b]
            jobs.append((cls, bi, seeds_with_user, MODELS[mi % len(MODELS)]))
            mi += 1
    print(f"{len(jobs)} generation jobs (3 seeds each, {VARIANTS_PER_BATCH} variants requested)", flush=True)
    with cf.ThreadPoolExecutor(max_workers=3) as ex:
        for key, status in ex.map(run_one, jobs):
            print(f"  {key}: {status}", flush=True)
    print("done")

if __name__ == "__main__":
    main()
